mapper.update:
UPDATE guacamole_connection_parameter
SET parameter_value      = #{newValue,jdbcType=VARCHAR},
    parameter_encryption = #{newEncryption,jdbcType=VARCHAR}
WHERE connection_id   = #{row.ownerIdentifier,jdbcType=INTEGER}
  AND parameter_name  = #{row.name,jdbcType=VARCHAR}
  AND parameter_value COLLATE Latin1_General_BIN2 = #{row.value,jdbcType=VARCHAR}
  AND (parameter_encryption = #{row.encryption,jdbcType=VARCHAR}
       OR (parameter_encryption IS NULL AND #{row.encryption,jdbcType=VARCHAR} IS NULL))

UPDATE guacamole_sharing_profile_parameter
SET parameter_value      = #{newValue,jdbcType=VARCHAR},
    parameter_encryption = #{newEncryption,jdbcType=VARCHAR}
WHERE sharing_profile_id = #{row.ownerIdentifier,jdbcType=INTEGER}
  AND parameter_name     = #{row.name,jdbcType=VARCHAR}
  AND parameter_value COLLATE Latin1_General_BIN2 = #{row.value,jdbcType=VARCHAR}
  AND (parameter_encryption = #{row.encryption,jdbcType=VARCHAR}
       OR (parameter_encryption IS NULL AND #{row.encryption,jdbcType=VARCHAR} IS NULL))
